?><!doctype html><html lang="<?= public_lang() ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= public_text('Личный кабинет — BYPCMS') ?></title><link rel="stylesheet" href="/account/account.css"></head><body><main><header><?= public_language_switch() ?><a href="<?= public_href('/') ?>">BYPCMS</a><a href="<?= public_href('/order/') ?>"><?= public_text('Новый заказ') ?></a><a href="<?= public_href('/contacts/') ?>"><?= public_text('Контакты и реквизиты') ?></a><?php if($customer):?><form method="post"><input type="hidden" name="csrf" value="<?= $e($_SESSION['customer_csrf']) ?>"><button name="action" value="logout"><?= public_text('Выйти') ?></button></form><?php endif ?></header><h1><?= public_text('Личный кабинет') ?></h1><?php if($error):?><p class="error" role="alert"><?= $e(public_t($error)) ?></p><?php endif ?>
